#!/usr/bin/env python3
# -*- coding: utf-8 -*-
# ==============================================================================
#  mohaa_entdefs.py  --  MOHAA entity definitions for the map viewer
#
#  Every placeable entity class has a definition: its editor colour, its default
#  box (point entities) or "?" (brush entities), the names of its spawnflag bits
#  and a short description. MOHRadiant reads these from /*QUAKED ... */ comment
#  headers: the game code's (shipped as code/*.cpp in entdefs.pk3) and every .tik
#  model's. This module does the same over the loaded paks, falling back to the
#  built-in table at the bottom (generated from OpenMoHAA's game code).
# ==============================================================================
import re

# /*QUAKED <classname> (r g b) (minx miny minz) (maxx maxy maxz) FLAG FLAG ...
# description
# */
# Brush entities write "?" instead of the two boxes. Some .tik headers leave out the
# space before the colour, e.g. "animate_fx_adam-firefill(0.0 0.5 0.5)".
_QUAKED = re.compile(r'/\*QUAKED[ \t]+([^\s(]+)[ \t]*\(([^)]*)\)[ \t]*'
                     r'(\?|\(([^)]*)\)[ \t]*\(([^)]*)\))?([^\n]*)\n(.*?)\*/', re.S)


def _floats(s, n):
    """The first n numbers of a space-separated string, or None if there are fewer."""
    out = []
    for tok in (s or "").split():
        try:
            out.append(float(tok))
        except ValueError:
            break
    return out[:n] if len(out) >= n else None


def parse_quaked(text, source=""):
    """Every /*QUAKED*/ definition in a file, as dicts."""
    out = []
    for m in _QUAKED.finditer(text or ""):
        name = m.group(1).strip()
        col = _floats(m.group(2), 3) or [0.5, 0.5, 0.5]
        brush = m.group(3) == "?"
        box = None
        if not brush and m.group(4) is not None:
            mn = _floats(m.group(4), 3)
            mx = _floats(m.group(5), 3)
            if mn and mx:
                box = (tuple(mn), tuple(mx))
        flags = tuple(m.group(6).split())
        desc = re.sub(r"\*{5,}", "", m.group(7)).replace("\t", "  ")
        desc = "\n".join(l.rstrip() for l in desc.splitlines()).strip()
        out.append({"name": name, "color": tuple(col), "brush": brush, "box": box,
                    "flags": flags, "desc": desc, "source": source})
    return out


class EntityDefs:
    """Class name -> definition, case-insensitive. Pak definitions override the
    built-in ones; tik_for_class maps a model's class name to its .tik path."""

    def __init__(self):
        self.defs = {}
        self.tik_for_class = {}
        self.class_for_tik = {}
        for name, (col, box, flags, desc) in BUILTIN.items():
            self.defs[name.lower()] = {"name": name, "color": col, "brush": box is None and name not in _POINT_NO_BOX,
                                       "box": box, "flags": flags, "desc": desc, "source": "built-in"}

    def add_text(self, text, source="", tik=None):
        """Add every definition in one file. tik: the .tik it came from, which then
        draws that class."""
        for d in parse_quaked(text, source):
            self.defs[d["name"].lower()] = d
            if tik:
                d["tik"] = tik
                self.tik_for_class[d["name"].lower()] = tik
                self.class_for_tik.setdefault(tik.lower(), d["name"])

    def scan_vfs(self, vfs, log=None):
        """Read every .tik and code/*.cpp|*.def in the loaded paks for definitions."""
        n = 0
        for k in list(vfs.names()):
            kl = k.lower()
            is_tik = kl.endswith(".tik")
            if not (is_tik or (kl.startswith("code/") and kl.endswith((".cpp", ".def", ".c")))):
                continue
            data = vfs.read(k)
            if not data or b"QUAKED" not in data:
                continue
            tik = None
            if is_tik:
                tik = kl[7:] if kl.startswith("models/") else kl
            self.add_text(data.decode("latin-1", "replace"), k, tik)
            n += 1
        if log:
            log("entity definitions: %d classes (%d files with QUAKED headers)" % (len(self.defs), n))
        return n

    def get(self, classname):
        """The definition of a class (any case), or None."""
        return self.defs.get((classname or "").lower())

    def static_classname(self, model_path):
        """Class name for a static model path such as "static//tree_oak.tik"."""
        p = (model_path or "").replace("\\", "/").lower()
        while "//" in p:
            p = p.replace("//", "/")
        if p.startswith("models/"):
            p = p[7:]
        return self.class_for_tik.get(p)


# The four extra check boxes MOHRadiant's entity window shows under every class's own
# flags (spawnflags 256, 512, 1024 and 2048, inherited from Quake 3's editor). The page
# names a node's or entity's set bits with these after the class's own.
EDITOR_FLAGS = {8: "!Easy", 9: "!Medium", 10: "!Hard", 11: "!DeathMatch"}


# Model classes: point entities even where a definition gives them no box (they take
# their model's size), never brush entities.
_POINT_NO_BOX = ("script_model", "misc_model", "script_model_realdamage")

